/* updateLastScheduledAt */
UPDATE sys_batch_config
   SET last_scheduled_at = #{lastScheduledAt}
     , upt_date          = CURRENT_TIMESTAMP
 WHERE bat_id = #{batId}

/* updateLastExecutedAt */
UPDATE sys_batch_config
   SET last_executed_at = #{lastExecutedAt}
     , upt_date         = CURRENT_TIMESTAMP
 WHERE bat_id = #{batId}
